/**
 * Diagnostic question assembler — derives claimType and claimReason
 * from 4 natural-language questions instead of a direct category picker.
 *
 * Flow:
 *   Step 1: Show STEP1_QUESTIONS (what_happened radio)
 *   Step 2: Based on what_happened, load STEP2_BY_TYPE[scenario]:
 *           – scenario-specific reason dropdown
 *           – date field
 *           – location / detail field
 *   Complete: all requiredIds answered → derive claimType + claimReason
 *
 * All data lives in question-definitions.json.  This function never
 * contains claim-type-specific values — edit the JSON to change questions.
 *
 * Input:
 *   answers      – { [questionId]: string }  accumulated user answers
 *   questionDefs – parsed question-definitions.json
 *
 * Output:
 *   questions    – FormField[]   ordered list to render in the UI
 *   isComplete   – boolean
 *   claimType    – string | null  e.g. "MOTOR", "MEDICAL"
 *   claimReason  – string | null  human-readable reason label
 */
const handler = (input) => {
  const answers     = input.answers || {};
  const defs        = input.questionDefs || {};
  const step1       = defs.STEP1_QUESTIONS || [];
  const step2ByType = defs.STEP2_BY_TYPE   || {};

  // Step 1 — what_happened not yet answered
  if (!answers.what_happened) {
    return {
      questions:   step1,
      isComplete:  false,
      claimType:   null,
      claimReason: null
    };
  }

  const scenario = answers.what_happened;
  const config   = step2ByType[scenario];

  // Guard: unknown scenario (shouldn't happen with valid UI options)
  if (!config) {
    return {
      questions:   step1,
      isComplete:  false,
      claimType:   null,
      claimReason: null
    };
  }

  const allQuestions = [...step1, ...(config.questions || [])];
  const requiredIds  = config.requiredIds || [];

  const isComplete = requiredIds.length > 0 &&
    requiredIds.every(id => !!answers[id] && answers[id] !== '');

  // Resolve human-readable claimReason from the reason dropdown label
  let claimReason = null;
  if (config.reasonField && answers[config.reasonField]) {
    const reasonQ = (config.questions || []).find(q => q.id === config.reasonField);
    if (reasonQ && reasonQ.options) {
      const opt = reasonQ.options.find(o => o.value === answers[config.reasonField]);
      claimReason = opt ? opt.label : answers[config.reasonField];
    } else {
      claimReason = answers[config.reasonField];
    }
  }

  return {
    questions:   allQuestions,
    isComplete:  isComplete,
    claimType:   isComplete ? config.claimType : null,
    claimReason: claimReason
  };
};
